export interface ShelfItem {
  id: number;
  label: string;
  tags: string[];
}

export class RecordShelf {
  private readonly items = new Map<number, ShelfItem>();

  add(item: ShelfItem): boolean {
    this.validateItem(item);
    if (this.items.has(item.id)) {
      return false;
    }
    this.items.set(item.id, this.copy(item));
    return true;
  }

  get(id: number): ShelfItem | null {
    this.validateId(id);
    const item = this.items.get(id);
    return item === undefined ? null : item;
  }

  update(item: ShelfItem): ShelfItem | null {
    this.validateItem(item);
    const previous = this.items.get(item.id);
    if (previous === undefined) {
      return null;
    }
    this.items.set(item.id, this.copy(item));
    return this.copy(previous);
  }

  remove(id: number): ShelfItem | null {
    this.validateId(id);
    const previous = this.items.get(id);
    if (previous === undefined) {
      return null;
    }
    this.items.delete(id);
    return this.copy(previous);
  }

  list(): ShelfItem[] {
    return Array.from(this.items.values(), (item) => this.copy(item));
  }

  private validateItem(item: ShelfItem): void {
    if (item === null || typeof item !== "object") {
      throw new TypeError("item must be an object");
    }
    this.validateId(item.id);
    if (typeof item.label !== "string" || item.label.trim().length === 0) {
      throw new TypeError("label must contain non-whitespace characters");
    }
    if (!Array.isArray(item.tags) || item.tags.some((tag) => typeof tag !== "string")) {
      throw new TypeError("tags must be an array of strings");
    }
  }

  private validateId(id: number): void {
    if (!Number.isSafeInteger(id) || id <= 0) {
      throw new RangeError("id must be a positive safe integer");
    }
  }

  private copy(item: ShelfItem): ShelfItem {
    return { id: item.id, label: item.label, tags: [...item.tags] };
  }
}

