import { RecordShelf, ShelfItem } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function itemEqual(actual: ShelfItem | null, expected: ShelfItem | null, message: string): void {
  if (expected === null) { equal(actual, null, message); return; }
  assert(actual !== null, `${message}: item missing`);
  equal(actual.id, expected.id, `${message}: id`);
  equal(actual.label, expected.label, `${message}: label`);
  equal(actual.tags.length, expected.tags.length, `${message}: tag count`);
  expected.tags.forEach((tag, index) => equal(actual.tags[index], tag, `${message}: tag ${index}`));
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof TypeError, message); return; }
  throw new Error(`${message}: did not throw`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof RangeError, message); return; }
  throw new Error(`${message}: did not throw`);
}

const shelf = new RecordShelf();
const emptyA = shelf.list();
const emptyB = shelf.list();
equal(emptyA.length, 0, 'empty list');
assert(emptyA !== emptyB, 'empty arrays are fresh');

const source: ShelfItem = { id: 1, label: ' first ', tags: [' vinyl ', ''] };
equal(shelf.add(source), true, 'add first');
source.label = 'changed';
source.tags[0] = 'changed';
source.tags.push('extra');
itemEqual(shelf.get(1), { id: 1, label: ' first ', tags: [' vinyl ', ''] }, 'input copied');
equal(shelf.add({ id: 1, label: 'duplicate', tags: ['x'] }), false, 'duplicate rejected');
itemEqual(shelf.get(1), { id: 1, label: ' first ', tags: [' vinyl ', ''] }, 'duplicate does not modify');

equal(shelf.add({ id: 2, label: 'second', tags: [] }), true, 'add second');
const fetched = shelf.get(1);
assert(fetched !== null, 'fetched item');
fetched.label = 'mutated';
fetched.tags[0] = 'mutated';
itemEqual(shelf.get(1), { id: 1, label: ' first ', tags: [' vinyl ', ''] }, 'get is deeply copied');
assert(shelf.get(1) !== shelf.get(1), 'get objects are fresh');

const replacement: ShelfItem = { id: 1, label: 'updated', tags: ['new'] };
const previous = shelf.update(replacement);
itemEqual(previous, { id: 1, label: ' first ', tags: [' vinyl ', ''] }, 'update returns previous');
replacement.tags[0] = 'changed later';
assert(previous !== null, 'previous exists');
previous.tags[0] = 'changed previous';
itemEqual(shelf.get(1), { id: 1, label: 'updated', tags: ['new'] }, 'update aliases isolated');
equal(shelf.update({ id: 99, label: 'missing', tags: [] }), null, 'missing update');
const ordered = shelf.list();
equal(ordered[0].id, 1, 'update retains position');
equal(ordered[1].id, 2, 'second retains position');
ordered[0].tags.push('mutation');
itemEqual(shelf.get(1), { id: 1, label: 'updated', tags: ['new'] }, 'list deeply copied');

itemEqual(shelf.remove(1), { id: 1, label: 'updated', tags: ['new'] }, 'remove returns item');
equal(shelf.remove(1), null, 'remove missing');
equal(shelf.list().length, 1, 'only matching item removed');
equal(shelf.list()[0].id, 2, 'remaining item');

for (const id of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1, Infinity, NaN]) {
  throwsRange(() => shelf.get(id), 'invalid get ID');
  throwsRange(() => shelf.remove(id), 'invalid remove ID');
  throwsRange(() => shelf.add({ id, label: 'ok', tags: [] }), 'invalid item ID');
}
throwsType(() => shelf.add(null as unknown as ShelfItem), 'null item');
throwsType(() => shelf.add({ id: 3, label: '   ', tags: [] }), 'blank label');
throwsType(() => shelf.add({ id: 3, label: 'ok', tags: ['ok', 4 as unknown as string] }), 'non-string tag');
throwsType(() => shelf.add({ id: 3, label: 'ok', tags: null as unknown as string[] }), 'non-array tags');
equal(shelf.list().length, 1, 'invalid operations leave shelf stable');

